//! Checks connected-component labelling against QuPath's own output.
//!
//! Fixture generated by `parity/java/RegionalMaxima.java` via
//! `./parity/record.sh`, recorded through `RoiLabeling.labelImage(ipTemp, 0,
//! false)` — the call that turns the prominence image into the markers
//! `Watershed.doWatershed` floods. Needs no slide.
//!
//! The input fed in here is the **recorded** prominence, not one this crate
//! computed, so a failure is about the labelling and cannot be about the stage
//! before it. `qupath-filters` checks that stage separately against the same
//! file.
//!
//! Label numbers are compared exactly rather than up to a permutation. They are
//! assigned in the raster order of each component's first pixel, and the
//! watershed floods them by number, so a relabelling is a different answer.

use qupath_watershed::{Connectivity, Labeller};

fn fixture() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../parity/fixtures/RegionalMaxima.json")
}

/// Extracts the text between two markers, starting the search at `from`.
fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

fn floats(text: &str) -> Vec<f32> {
    text.split(',')
        .map(|v| v.trim().parse().expect("float"))
        .collect()
}

fn scalar(text: &str, key: &str, from: usize) -> (f64, usize) {
    let (value, at) = between(text, &format!("\"{key}\": "), ",", from);
    (value.trim().parse().expect(key), at)
}

#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "recorded dimensions and counts are small positive integers"
)]
fn index(value: f64) -> usize {
    value as usize
}

#[test]
fn matches_qupath_label_image() {
    let path = fixture();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));
    let (cases, _) = between(&text, "\"maxima\": [", "\n  ]\n}", 0);

    let mut count = 0usize;
    let mut markers = 0u32;
    let mut at = 0usize;
    // One labeller across every case on purpose: a stack left dirty by a
    // previous shape would show up here and nowhere else.
    let mut labeller = Labeller::new();
    while let Some(start) = cases[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(cases, "\"name\": \"", "\"", from);
        let (width, next) = scalar(cases, "width", next);
        let (height, next) = scalar(cases, "height", next);
        let (_, next) = scalar(cases, "threshold", next);
        let (expected_count, next) = scalar(cases, "labelCount", next);
        let (_, next) = between(cases, "\"in\": [", "]", next);
        let (prominence_text, next) = between(cases, "\"prominence\": [", "]", next);
        let (labels_text, next) = between(cases, "\"labels\": [", "]", next);
        at = next;

        let (width, height) = (index(width), index(height));
        let prominence = floats(prominence_text);
        let theirs = floats(labels_text);
        assert_eq!(
            prominence.len(),
            width * height,
            "{name}: {} prominence values for {width}x{height}",
            prominence.len()
        );

        let mut ours = vec![0.0f32; prominence.len()];
        // `labelImage(ipTemp, 0, false)`: threshold zero, 4-connected.
        let found = labeller.label_into(&prominence, &mut ours, width, 0.0, Connectivity::Four);

        assert_eq!(
            u64::from(found),
            index(expected_count) as u64,
            "{name}: {found} components against QuPath's {}",
            index(expected_count)
        );
        for (at, (&ours, &theirs)) in ours.iter().zip(&theirs).enumerate() {
            assert_eq!(
                ours,
                theirs,
                "{name}: at {at} ({}, {}) we label {ours}, QuPath labels {theirs}",
                at % width,
                at / width
            );
        }

        println!("{name:>22}  {width:>3}x{height:<3}  {found:>3} components");
        markers += found;
        count += 1;
    }

    assert!(count >= 13, "only {count} cases in the fixture");

    for (name, why) in [
        (
            "diagonal-touch",
            "the labelling is 4-connected where the maxima test was 8-connected",
        ),
        (
            "shoulder-plateau",
            "a zero prominence is background, however large the terrace",
        ),
        (
            "log-tile",
            "the marker count on the input this stage meets in the pipeline",
        ),
    ] {
        assert!(cases.contains(name), "{name} missing: {why} is unchecked");
    }

    println!("{count} surfaces  {markers} markers, all labelled identically");
}
